-- Starter catalogue seed for YAZ Education V18.
-- The website still has local TypeScript data as a fallback while the database is being populated.
-- These rows give Supabase a real starting catalogue and may be safely re-run.

on conflict (slug) do update set
  name=excluded.name, short_name=excluded.short_name, arabic_name=excluded.arabic_name,
  city=excluded.city, institution_type=excluded.institution_type, campus=excluded.campus,
  overview_en=excluded.overview_en, overview_ar=excluded.overview_ar,
  study_areas_en=excluded.study_areas_en, study_areas_ar=excluded.study_areas_ar,
  official_url=excluded.official_url, logo_path=excluded.logo_path,
  verified=excluded.verified, verified_at=excluded.verified_at, updated_at=now();

on conflict (slug) do update set
  name=excluded.name, short_name=excluded.short_name, arabic_name=excluded.arabic_name,
  city=excluded.city, institution_type=excluded.institution_type,
  overview_en=excluded.overview_en, overview_ar=excluded.overview_ar,
  course_types_en=excluded.course_types_en, course_types_ar=excluded.course_types_ar,
  official_url=excluded.official_url, logo_path=excluded.logo_path,
  verified=excluded.verified, verified_at=excluded.verified_at, updated_at=now();

